head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDBNF50000";
scwin.dmenus = undefined;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — saleInstId, salesInstList

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf50000.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_21", fn: function(){ return ((dlt_salesInstList.getCellData(0, "saleInstId") ?? (() => { throw new Error("unresolved:" + "entity.saleInstId"); })()) === (dma_pageContext.get("saleInstId") ?? "")); } }, { id: "c_otherwise_23", fn: function(){ return (!(((dlt_salesInstList.getCellData(0, "saleInstId") ?? (() => { throw new Error("unresolved:" + "entity.saleInstId"); })()) === (dma_pageContext.get("saleInstId") ?? "")))); } }, { id: "c_if_14", fn: function(){ return ((((dma_pageContext.get("salesInstList") ?? "")) && typeof ((dma_pageContext.get("salesInstList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("salesInstList") ?? "")).getRowCount() : ((((dma_pageContext.get("salesInstList") ?? "")) == null) ? 0 : (((dma_pageContext.get("salesInstList") ?? "")).length || 0))) > 0); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_19", entity: "dlt_salesInstList", countIds: [], cells: [{ childId: "option_22", fn: function (v, i) { return String(v("saleInstId")) + "," + String(v("bndClssCd")) + "," + String(v("isurCd")) + "," + String(v("bndInstCd")); } }, { childId: "__rc2", fn: function (v, i) { return "[" + String(v("instNm")) + "] " + String(v("saleInst")); } }, { childId: "option_24", fn: function (v, i) { return String(v("saleInstId")) + "," + String(v("bndClssCd")) + "," + String(v("isurCd")) + "," + String(v("bndInstCd")); } }, { childId: "__rc3", fn: function (v, i) { return "[" + String(v("instNm")) + "] " + String(v("saleInst")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("bndMktactTpNm") ?? ""))); } },
        { childId: "__rb1", fn: function () { return String(String((dma_pageContext.get("bndMktactTpNm") ?? ""))); } },
        { childId: "ipt_bndMktactTpCd", fn: function () { return String(String((dma_pageContext.get("bndMktactTpCd") ?? ""))); } },
        { childId: "__rb4", fn: function () { return String(String((dma_pageContext.get("saleInstNm") ?? ""))); } },
        { childId: "__rb5", fn: function () { return String(String((dma_pageContext.get("saleIsuNm") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.dmenus = { "bmenu": 0, "mmenu": 0 };
        $('div#header').trigger('mouseleave');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf50000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 키 sales 를 쓰는 tx 가 3개다(tx_fn_searchList, tx_fn_openRequest, tx_fnSelectChange)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_salesInstList_onchange
 * @description slc_salesInstList 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_salesInstList_onchange = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.fnSelectChange(selfVar.value);

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf50000.slc_salesInstList_onchange' }); }
};

/**
 * @method
 * @name btn_searchList_onclick
 * @description btn_searchList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchList_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf50000.btn_searchList_onclick' }); }
};

/**
 * @method
 * @name ipt_searchWord_onkeypress
 * @description ipt_searchWord onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_searchWord_onkeypress = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.str.replaceAll(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf50000.ipt_searchWord_onkeypress' }); }
};

/**
 * @method
 * @name ipt_searchWord_onpaste
 * @description ipt_searchWord onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_searchWord_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf50000.ipt_searchWord_onpaste' }); }
};

/**
 * @method
 * @name grd_result_oncellclick
 * @description grd_result 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        /* TODO Stage2: 행 동작 미정의: scwin.detail (열 ?) */ await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.detail'); return;
        await scwin.openRequest(r["isuCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};

/**
 * @method
 * @name __on_enter_3_ipt_searchword
 * @description on enter 3 ipt searchword 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_3_ipt_searchword = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.searchList() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf50000.__on_enter_3_ipt_searchWord' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_91_onclick
 * @description krxpage_pagenavigator_91 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_91_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_searchListReq').set('pageIndex', pi);
        await scwin.searchList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldbnf50000.krxpage_pagenavigator_91_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function (action) {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: action ?? "/sales/sales.do",
        ref: "dma_searchListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_openRequest
 * @description open Request 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_openRequest = async function (action) {
    const sbmOptions = {
        id: "tx_fn_openRequest",
        method: "post",
        action: action ?? "/sales/sales.do",
        ref: "dma_openRequestReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSelectChange
 * @description fn Select Change 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSelectChange = async function () {
    const sbmOptions = {
        id: "tx_fnSelectChange",
        method: "post",
        action: "/sales/sales.do?bnd_mktact_tp_cd=320",
        ref: "dma_fnSelectChangeReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_searchListReq').set('pageIndex', "1");
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    $c.util.getComponent('dma_searchListReq').set('method', "salesReportReqList");
    await scwin.tx_fn_searchList('/sales/sales.do');
};

/**
 * @method
 * @name openRequest
 * @description open Request 처리
 * @param {*} _std_cd _std_cd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openRequest = async function (_std_cd) {
    const _bnd_mktact_tp_cd = $c.util.getComponent("dma_searchListReq").get("bndMktactTpCd");
    $c.util.getComponent("dma_searchListReq").set("stdCd", _std_cd);
    $c.util.getComponent('dma_searchListReq').set('method', "salesReportReqView");
    await scwin.tx_fn_openRequest('/sales/sales.do');
};

/**
 * @method
 * @name fnSelectChange
 * @description fn Select Change 처리
 * @param {*} val val
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSelectChange = async function (val) {
    $c.util.getComponent('dma_searchListReq').set('salesInstVal', val);
    $c.util.getComponent('dma_searchListReq').set('method', "salesReportReqList");
    await scwin.tx_fnSelectChange();
};
